type Pembayaran =
  | { jenis: "tunai"; uang: number }
  | { jenis: "kartu"; bank: string; biaya: number }
  | { jenis: "qris"; idTransaksi: string };

function keterangan(p: Pembayaran): string {
  switch (p.jenis) {
    case "tunai":
      return "Tunai " + p.uang;
    case "kartu":
      return `Kartu ${p.bank} (biaya ${p.biaya})`;
    case "qris":
      return "QRIS " + p.idTransaksi;
  }
}
const transaksi: Pembayaran[] = [
  { jenis: "kartu", bank: "BNI", biaya: 2000 },
  { jenis: "qris", idTransaksi: "QR-778" },
];
for (const t of transaksi) console.log(keterangan(t));

