type Bentuk = { kind: "kotak"; p: number; l: number } | { kind: "segitiga"; alas: number; tinggi: number };
function luas(b: Bentuk): number {
  switch (b.kind) {
    case "kotak":
      return b.p * b.l;
    case "segitiga":
      return (b.alas * b.tinggi) / 2;
  }
}
console.log("luas", luas({ kind: "kotak", p: 3, l: 4 }));
console.log("luas", luas({ kind: "segitiga", alas: 2, tinggi: 3 }));

