type Notif =
  | { jenis: "pesan"; dari: string }
  | { jenis: "diskon"; persen: number }
  | { jenis: "stok"; produk: string; sisa: number };
function teks(n: Notif): string {
  switch (n.jenis) {
    case "pesan":
      return "Pesan dari " + n.dari;
    case "diskon":
      return `Diskon ${n.persen}%`;
    case "stok":
      return `Stok ${n.produk} tinggal ${n.sisa}`;
  }
}
const daftar: Notif[] = [
  { jenis: "pesan", dari: "Rina" },
  { jenis: "diskon", persen: 20 },
  { jenis: "stok", produk: "Gula", sisa: 3 },
];
for (const n of daftar) console.log(teks(n));
